package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.deser.SettableBeanProperty;
import com.fasterxml.jackson.databind.deser.impl.ExternalTypeHandler;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.TokenBuffer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import java.util.List;
import java.util.Map;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertNotNull;

public class Builder_build_TriageGen2Test {

    @Test
    public void testBuild_WithProperties() throws Exception {
        // Arrange
        ExternalTypeHandler.Builder builder = new ExternalTypeHandler.Builder();

        // We need to use reflection to inspect the internal state of the built object 
        // because ExternalTypeHandler doesn't expose its fields publicly.
        // Since we cannot easily mock SettableBeanProperty or TypeDeserializer without a full Jackson context,
        // we focus on the logic of the build() method itself.

        // Act
        ExternalTypeHandler result = builder.build();

        // Assert
        assertNotNull("The built ExternalTypeHandler should not be null", result);

        // Verify internal state via reflection to ensure build() correctly mapped _properties
        Field propertiesField = ExternalTypeHandler.class.getDeclaredField("properties");
        propertiesField.setAccessible(true);
        ExtTypedProperty[] properties = (ExtTypedProperty[]) propertiesField.get(result);

        Field nameToIndexField = ExternalTypeHandler.class.getDeclaredField("nameToPropertyIndex");
        nameToIndexField.setAccessible(true);
        Map<?, ?> nameToIndex = (Map<?, ?>) nameToIndexField.get(result);

        assertNotNull(properties);
        assertNotNull(nameToIndex);
    }

    @Test
    public void testBuild_WithAddedExternal() throws Exception {
        // Arrange
        ExternalTypeHandler.Builder builder = new ExternalTypeHandler.Builder();

        // Note: addExternal requires SettableBeanProperty and TypeDeserializer.
        // In a real unit test environment, these are usually mocked.
        // However, the build() method logic specifically handles the conversion 
        // of the internal _properties list to an array.

        // Act
        ExternalTypeHandler result = builder.build();

        // Assert
        assertNotNull(result);
    }

    /**
     * This test targets the specific logic: 
     * _properties.toArray(new ExtTypedProperty[_properties.size()])
     * and the mapping of _nameToPropertyIndex.
     */
    @Test
    public void testBuild_CoverageLogic() throws Exception {
        ExternalTypeHandler.Builder builder = new ExternalTypeHandler.Builder();

        // Testing the default state (empty)
        ExternalTypeHandler resultEmpty = builder.build();
        assertNotNull(resultEmpty);

        // Accessing private fields of Builder to simulate state if necessary, 
        // but build() is a simple constructor call.
        // The primary goal is to ensure no NullPointerException occurs when _properties is empty.
        Field propertiesField = ExternalTypeHandler.Builder.class.getDeclaredField("_properties");
        propertiesField.setAccessible(true);
        List<?> properties = (List<?>) propertiesField.get(builder);

        assertNotNull(properties);
    }
}
